@Override
public String codegen(String resultVar, String pbObjectCode, int indent) throws PbCodegenException {
    // the type of pbObjectCode must not be primitive type,
    // it should convert to internal flink row type like StringData.
    PbCodegenAppender appender = new PbCodegenAppender(indent);
    switch (fd.getJavaType()) {
        case INT :
        case LONG :
        case FLOAT :
        case DOUBLE :
        case BOOLEAN :
            appender.appendLine((resultVar + " = ") + pbObjectCode);
            break;
        case BYTE_STRING :
            appender.appendLine(((resultVar + " = ") + pbObjectCode) + ".toByteArray()");
            break;
        case STRING :
            appender.appendLine(((resultVar + " = BinaryStringData.fromString(") + pbObjectCode) + ".toString())");
            break;
        case ENUM :
            if ((logicalType.getTypeRoot() == LogicalTypeRoot.CHAR) || (logicalType.getTypeRoot() == LogicalTypeRoot.VARCHAR)) {
                appender.appendLine(((resultVar + " = BinaryStringData.fromString(") + pbObjectCode) + ".toString())");
            } else if ((((logicalType.getTypeRoot() == LogicalTypeRoot.TINYINT) || (logicalType.getTypeRoot() == LogicalTypeRoot.SMALLINT)) || (logicalType.getTypeRoot() == LogicalTypeRoot.INTEGER)) || (logicalType.getTypeRoot() == LogicalTypeRoot.BIGINT)) {
                appender.appendLine(((resultVar + " = ") + pbObjectCode) + ".getNumber()");
            } else {
                throw new PbCodegenException("Illegal type for protobuf enum, only char/vachar/int/bigint is supported");
            }
            break;
        default :
            throw new PbCodegenException("Unsupported protobuf simple type: " + fd.getJavaType());
    }
    return appender.code();
}

